import java.util.*;

class Solution {
  private static final int MOD = 1_000_000_007;

  public int[] pathsWithMaxScore(List<String> board) {
    int n = board.size();
    int[][] best = new int[n][n], ways = new int[n][n];
    for (int[] row : best) Arrays.fill(row, -1);
    best[n - 1][n - 1] = 0;
    ways[n - 1][n - 1] = 1;
    // moves go up, left or up-left, so a cell is reached from below, the right, or diagonally below-right
    int[][] from = {{1, 0}, {0, 1}, {1, 1}};
    for (int r = n - 1; r >= 0; r--) {
      for (int c = n - 1; c >= 0; c--) {
        char ch = board.get(r).charAt(c);
        if (ch == 'X' || (r == n - 1 && c == n - 1)) continue;
        int value = -1, count = 0;
        for (int[] d : from) {
          int rr = r + d[0], cc = c + d[1];
          if (rr >= n || cc >= n || best[rr][cc] < 0) continue;
          if (best[rr][cc] > value) {
            value = best[rr][cc];
            count = ways[rr][cc];
          } else if (best[rr][cc] == value) count = (count + ways[rr][cc]) % MOD;
        }
        if (value >= 0) {
          best[r][c] = value + (Character.isDigit(ch) ? ch - '0' : 0);
          ways[r][c] = count;
        }
      }
    }
    return best[0][0] < 0 ? new int[] {0, 0} : new int[] {best[0][0], ways[0][0]};
  }
}
